function runMaze(canvasId){
    // Helper: get canvas and context
    const canvas=document.getElementById(canvasId);
    if(!canvas||!canvas.getContext)throw new Error('Canvas not found or unsupported');
    const ctx=canvas.getContext('2d');
    const width=canvas.width;
    const height=canvas.height;
    const cols=25; // number of cells horizontally
    const rows=25; // number of cells vertically
    const cellW=width/cols;
    const cellH=height/rows;
    // grid: 0=empty,1=wall
    const grid=Array.from({length:rows},()=>Array(cols).fill(0));
    const steps=[]; // visualization steps

    // Drawing utilities
    function drawCell(x,y,color){
        ctx.fillStyle=color;
        ctx.fillRect(x*cellW,y*cellH,cellW,cellH);
    }
    function drawGrid(){
        ctx.clearRect(0,0,width,height);
        for(let y=0;y<rows;y++){
            for(let x=0;x<cols;x++){
                drawCell(x,y,grid[y][x]===1?'#000':'#fff');
            }
        }
    }
    // Initialize border walls
    for(let i=0;i<cols;i++){
        grid[0][i]=1;
        grid[rows-1][i]=1;
        steps.push({type:'wall',x:i,y:0});
        steps.push({type:'wall',x:i,y:rows-1});
    }
    for(let j=0;j<rows;j++){
        grid[j][0]=1;
        grid[j][cols-1]=1;
        steps.push({type:'wall',x:0,y:j});
        steps.push({type:'wall',x:cols-1,y:j});
    }
    // Recursive division algorithm
    function divide(x,y,w,h,orientation){
        if(w<2||h<2)return;
        const horiz=orientation==='horizontal';
        const wx=x+ (horiz?0:Math.floor(Math.random()*(w-2)));
        const wy=y+ (horiz?Math.floor(Math.random()*(h-2)):0);
        const px=wx+ (horiz?Math.floor(Math.random()*w):0);
        const py=wy+ (horiz?0:Math.floor(Math.random()*h));
        const length=horiz?w:h;
        const dirX=horiz?1:0;
        const dirY=horiz?0:1;
        for(let i=0;i<length;i++){
            const cx=wx+ i*dirX;
            const cy=wy+ i*dirY;
            if(cx===px&&cy===py)continue;
            grid[cy][cx]=1;
            steps.push({type:'wall',x:cx,y:cy});
        }
        const nx=x, ny=y, nw=horiz?w:h, nh=horiz?h:w;
        const sub1={x:nx,y:ny,w:horiz?w:h,h:horiz?h:w};
        const sub2={x:horiz?wx+1:x+ (horiz?0:w),y:horiz?y:wy+1,w:horiz?w:h-1,h:horiz?h-1:w};
        const o1=chooseOrientation(sub1.w,sub1.h);
        const o2=chooseOrientation(sub2.w,sub2.h);
        divide(sub1.x,sub1.y,sub1.w,sub1.h,o1);
        divide(sub2.x,sub2.y,sub2.w,sub2.h,o2);
    }
    function chooseOrientation(w,h){
        if(w<h)return 'horizontal';
        if(h<w)return 'vertical';
        return Math.random()<0.5?'horizontal':'vertical';
    }
    // Start division inside the border
    divide(1,1,cols-2,rows-2,chooseOrientation(cols-2,rows-2));
    // A* solving
    const start={x:1,y:1};
    const goal={x:cols-2,y:rows-2};
    function heuristic(a,b){
        return Math.abs(a.x-b.x)+Math.abs(a.y-b.y);
    }
    function astar(){
        const open=[];
        const closed=new Set();
        const cameFrom={};
        const gScore=Array.from({length:rows},()=>Array(cols).fill(Infinity));
        const fScore=Array.from({length:rows},()=>Array(cols).fill(Infinity));
        gScore[start.y][start.x]=0;
        fScore[start.y][start.x]=heuristic(start,goal);
        open.push({x:start.x,y:start.y,f:fScore[start.y][start.x]});
        while(open.length){
            // sort by f
            open.sort((a,b)=>a.f-b.f);
            const current=open.shift();
            const key=current.y+','+current.x;
            if(closed.has(key))continue;
            closed.add(key);
            steps.push({type:'visit',x:current.x,y:current.y});
            if(current.x===goal.x&&current.y===goal.y){
                // reconstruct path
                let cx=goal.x, cy=goal.y;
                while(!(cx===start.x&&cy===start.y)){
                    steps.push({type:'solution',x:cx,y:cy});
                    const prev=cameFrom[cy+','+cx];
                    cx=prev.x; cy=prev.y;
                }
                steps.push({type:'solution',x:start.x,y:start.y});
                return;
            }
            const neighbors=[[1,0],[-1,0],[0,1],[0,-1]];
            for(const [dx,dy] of neighbors){
                const nx=current.x+dx, ny=current.y+dy;
                if(nx<0||ny<0||nx>=cols||ny>=rows)continue;
                if(grid[ny][nx]===1)continue; // wall
                const neighborKey=ny+','+nx;
                if(closed.has(neighborKey))continue;
                const tentativeG=gScore[current.y][current.x]+1;
                if(tentativeG<gScore[ny][nx]){
                    cameFrom[neighborKey]={x:current.x,y:current.y};
                    gScore[ny][nx]=tentativeG;
                    fScore[ny][nx]=tentativeG+heuristic({x:nx,y:ny},goal);
                    open.push({x:nx,y:ny,f:fScore[ny][nx]});
                    steps.push({type:'frontier',x:nx,y:ny});
                }
            }
        }
    }
    astar();
    // Visualization loop
    let i=0;
    function step(){
        if(i>=steps.length){
            clearInterval(timer);
            drawGrid(); // final state
            return;
        }
        const s=steps[i];
        if(s.type==='wall'){
            drawCell(s.x,s.y,'#000');
        }else if(s.type==='visit'){
            drawCell(s.x,s.y,'#add8e6'); // light blue
        }else if(s.type==='frontier'){
            drawCell(s.x,s.y,'#ffa500'); // orange
        }else if(s.type==='solution'){
            drawCell(s.x,s.y,'#0f0'); // green
        }
        i++;
    }
    drawGrid();
    const timer=setInterval(step,30);
}
